  for (const [scriptName, scriptValue] of Object.entries(scripts)) {
    if (/\bnpm\s+(install|ci)\b/.test(scriptValue)) {
      fail(`${packagePath} script ${scriptName} must not run ${scriptValue}`);
    }
  }
}

