  --state <name>           Initial state
  --assignee <email|me|uuid>  Initial assignee
  --labels "a,b"           Labels (comma-separated)

EXAMPLES:
  streamlinear-cli search                          # Your active issues
  streamlinear-cli search "auth bug"               # Text search
  streamlinear-cli --token abc123 search           # With explicit token
  streamlinear-cli --token-cmd "op read 'op://vault/linear/token'" search
  streamlinear-cli get ABC-123                     # Get issue details
  streamlinear-cli update ABC-123 --state Done     # Mark as done
  streamlinear-cli update ABC-123 --labels "bug,urgent"  # Replace labels
  streamlinear-cli comment ABC-123 "Fixed it"      # Add comment
  streamlinear-cli create --team ENG --title "Bug" # Create issue
`);
}

// Parse command line arguments
function parseArgs(args: string[]): { command: string; positional: string[]; flags: Record<string, string | null> } {
  const positional: string[] = [];
  const flags: Record<string, string | null> = {};
  let command: string | null = null;

  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg.startsWith("--")) {
      const key = arg.slice(2);
      const next = args[i + 1];
      if (next !== undefined && !next.startsWith("--")) {
        flags[key] = next;
        i++;
      } else {
        flags[key] = null;
      }
    } else if (!command) {
      // First non-flag argument is the command
      command = arg;
    } else {
      positional.push(arg);
    }
  }

  return { command: command || "help", positional, flags };
}

// Split a comma-separated labels flag value. An explicit empty string means
// "clear all labels", so it must round-trip as an empty array; a missing
// flag means no labels at all.
function parseLabels(value: string | null | undefined): string[] | undefined {
  if (value === undefined || value === null) return undefined;
  return value.split(",").map((label) => label.trim()).filter(Boolean);
}

// Resolve API token from various sources
function resolveToken(flags: Record<string, string | null>): string | null {
  // 1. Direct token flag
  if (flags.token) {
    return flags.token;
  }

  // 2. Token command
  if (flags["token-cmd"]) {
    try {
      const result = execSync(flags["token-cmd"], {
        encoding: "utf-8",
        stdio: ["pipe", "pipe", "pipe"],
      });
      return result.trim();
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      console.error(`Error running token command: ${message}`);
      process.exit(1);
    }
  }

  // 3. Environment variable
  return process.env.LINEAR_API_TOKEN || null;
}

// Main CLI entry point
async function main(): Promise<void> {
  const args = process.argv.slice(2);
  const { command, positional, flags } = parseArgs(args);

  // Help doesn't require API token
  if (command === "help" || command === "--help" || command === "-h") {
    printHelp();
    return;
  }

  // Resolve and set API token
  const token = [REDACTED];
  if (!token) {
    console.error("Error: No API token provided. Use --token, --token-cmd, or set LINEAR_API_TOKEN");
    process.exit(1);
  }
  setApiToken(token);

  try {
    let result: string;

    switch (command) {
      case "search": {
        if (positional.length > 0) {
          // Text search
          result = await handleSearch(positional.join(" "));
        } else if (Object.keys(flags).length > 0) {
          // Filter search
          const query: Record<string, unknown> = {};
          if (flags.state) query.state = flags.state;
          if (flags.assignee) query.assignee = flags.assignee;
          if (flags.priority) query.priority = parseInt(flags.priority, 10);
          if (flags.team) query.team = flags.team;
          result = await handleSearch(query);
        } else {
          // Default: my active issues
          result = await handleSearch();
        }
        break;
      }

      case "get": {
        const id = positional[0];
        if (!id) {
          console.error("Error: Issue ID is required");
          console.error("Usage: streamlinear-cli get <id>");
          process.exit(1);
        }
        result = await handleGet(id);
        break;
      }

      case "update": {
        const id = positional[0];
        if (!id) {
          console.error("Error: Issue ID is required");
          console.error("Usage: streamlinear-cli update <id> [--state <name>] [--priority <0-4>] [--assignee <email|me|uuid|null>] [--labels \"a,b\"]");
          process.exit(1);
        }
        const updates: { state?: string; priority?: number; assignee?: string | null; labels?: string[] } = {};
        if (flags.state) updates.state = flags.state;
        if (flags.priority) updates.priority = parseInt(flags.priority, 10);
        if (flags.assignee !== undefined) {
          updates.assignee = flags.assignee === "null" ? null : flags.assignee;
        }
        const labels = parseLabels(flags.labels);
        if (labels !== undefined) updates.labels = labels;
        if (Object.keys(updates).length === 0) {
          console.error("Error: At least one update option is required");
          console.error("Usage: streamlinear-cli update <id> [--state <name>] [--priority <0-4>] [--assignee <email|me|uuid|null>] [--labels \"a,b\"]");
          process.exit(1);
        }
        result = await handleUpdate(id, updates);
        break;
      }

      case "comment": {
        const id = positional[0];
        const body = positional.slice(1).join(" ") || flags.body;
        if (!id || !body) {
          console.error("Error: Issue ID and comment body are required");
          console.error("Usage: streamlinear-cli comment <id> <body>");
          process.exit(1);
        }
        result = await handleComment(id, body);
        break;
      }

      case "create": {
        const title = flags.title;
        const team = flags.team;
        if (!title || !team) {
          console.error("Error: --title and --team are required");
          console.error("Usage: streamlinear-cli create --title <title> --team <key> [--body <description>] [--priority <0-4>] [--state <name>] [--assignee <email|me|uuid>] [--labels \"a,b\"]");
          process.exit(1);
        }
        const options: { body?: string; priority?: number; state?: string; assignee?: string; labels?: string[] } = {};
        if (flags.body) options.body = flags.body;
        if (flags.priority) options.priority = parseInt(flags.priority, 10);
        if (flags.state) options.state = flags.state;
        if (flags.assignee) options.assignee = flags.assignee;
        const labels = parseLabels(flags.labels);
        if (labels && labels.length > 0) options.labels = labels;
        result = await handleCreate(title, team, options);
        break;
      }

      case "graphql": {
        const query = positional.join(" ");
        if (!query) {
          console.error("Error: GraphQL query is required");
          console.error("Usage: streamlinear-cli graphql <query>");
          process.exit(1);
        }
        result = await handleGraphql(query);
        break;
      }

      case "teams": {
        const teams = await getTeams();
        result = "Available teams and workflow states:\n\n";
        for (const team of teams) {
          const states = (team.states as { nodes: Array<{ name: string }> }).nodes;
          const stateNames = states.map((s) => s.name).join(", ");
          result += `${team.key} (${team.name})\n  States: ${stateNames}\n\n`;
        }
        break;
      }

      default:
        console.error(`Unknown command: ${command}`);
        console.error("Run 'streamlinear-cli help' for usage");
        process.exit(1);
    }

    console.log(result);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`Error: ${message}`);
    process.exit(1);
  }
}

main();

import { z } from "zod";

const LINEAR_API = "https://api.linear.app/graphql";

// API token - can be set programmatically or from env
let apiToken: string | undefined = process.env.LINEAR_API_TOKEN;

// Get API token
export function getApiToken(): string | undefined {
  return apiToken;
}

// Set API token programmatically
export function setApiToken(token: string): void {
  apiToken = token;
}

// Post-only mode: when STREAMLINEAR_POST_ONLY is set, the server refuses the
// read actions (search, get, graphql) so an agent can create and update
// issues without being able to read issue content. Internal lookups (teams,
// states, users, labels) still happen; they expose company data, not issue
// content.
export function isPostOnly(): boolean {
  const value = process.env.STREAMLINEAR_POST_ONLY;
  return value === "1" || (value !== undefined && value.toLowerCase() === "true");
}

// GraphQL helper
export async function graphql(query: string, variables: Record<string, unknown> = {}): Promise<unknown> {
  const token = [REDACTED];
  if (!token) {
    throw new Error("LINEAR_API_TOKEN environment variable is required");
  }

  const response = await fetch(LINEAR_API, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: token,
    },
    body: JSON.stringify({ query, variables }),
  });

  const json = await response.json() as { data?: unknown; errors?: Array<{ message: string }> };

  if (json.errors) {
    throw new Error(json.errors.map((e) => e.message).join("\n"));
  }

  return json.data;
}

// ID resolution: handles ABC-123, URLs, and UUIDs
export function resolveId(input: string): string {
  // Linear URL pattern
  const urlMatch = input.match(/linear\.app\/[^/]+\/issue\/([A-Z]+-\d+)/i);
  if (urlMatch) return urlMatch[1];

  // Already a short ID (ABC-123)
  if (/^[A-Z]+-\d+$/i.test(input)) return input.toUpperCase();

  // UUID - return as-is
  return input;
}

// Format issue for readable output
export function formatIssue(issue: Record<string, unknown>): string {
  const lines = [
    `**${issue.identifier}**: ${issue.title}`,
    `State: ${(issue.state as Record<string, unknown>)?.name || "Unknown"} | Priority: ${priorityName(issue.priority as number)} | Assignee: ${(issue.assignee as Record<string, unknown>)?.name || "Unassigned"}`,
  ];

  if (issue.dueDate) lines.push(`Due: ${issue.dueDate}`);
  if (issue.description) lines.push("", issue.description as string);
  if (issue.url) lines.push("", `Link: ${issue.url}`);

  return lines.join("\n");
}

export function priorityName(p: number): string {
  return ["No priority", "Urgent", "High", "Medium", "Low"][p] || "Unknown";
}

// Format issue list
export function formatIssueList(issues: Array<Record<string, unknown>>): string {
  if (issues.length === 0) return "No issues found.";

  return issues.map((issue) => {
    const state = (issue.state as Record<string, unknown>)?.name || "?";
    const priority = priorityName(issue.priority as number);
    const assignee = (issue.assignee as Record<string, unknown>)?.name || "Unassigned";
    return `- **${issue.identifier}** [${state}] ${issue.title} (${priority}, ${assignee})`;
  }).join("\n");
}

// Cache for workflow states and team info
let cachedViewer: Record<string, unknown> | null = null;
let cachedTeams: Array<Record<string, unknown>> | null = null;

export async function getViewer(): Promise<Record<string, unknown>> {
  if (cachedViewer) return cachedViewer;

  const data = await graphql(`query { viewer { id name email } }`) as { viewer: Record<string, unknown> };
  cachedViewer = data.viewer;
  return cachedViewer;
}

export async function getTeams(): Promise<Array<Record<string, unknown>>> {
  if (cachedTeams) return cachedTeams;

  const data = await graphql(`
    query {
      teams {
        nodes {
          id
          key
          name
          states { nodes { id name type } }
        }
      }
    }
  `) as { teams: { nodes: Array<Record<string, unknown>> } };

  cachedTeams = data.teams.nodes;
  return cachedTeams;
}

// Fuzzy match state name
export async function resolveState(teamId: string, stateName: string): Promise<string | null> {
  const teams = await getTeams();
  const team = teams.find((t) => t.id === teamId);
  if (!team) return null;

  const states = (team.states as { nodes: Array<Record<string, unknown>> }).nodes;
  const lower = stateName.toLowerCase();

  // Exact match first
  let match = states.find((s) => (s.name as string).toLowerCase() === lower);
  if (match) return match.id as string;

  // Partial match
  match = states.find((s) => (s.name as string).toLowerCase().includes(lower));
  if (match) return match.id as string;

  // Common aliases
  const aliases: Record<string, string[]> = {
    "done": ["done", "complete", "completed", "finished"],
    "in progress": ["in progress", "started", "doing", "wip", "in prog"],
    "todo": ["todo", "to do", "backlog", "open"],
    "canceled": ["canceled", "cancelled", "closed", "wontfix"],
  };

  for (const [canonical, alts] of Object.entries(aliases)) {
    if (alts.includes(lower)) {
      match = states.find((s) => (s.name as string).toLowerCase().includes(canonical));
      if (match) return match.id as string;
    }
  }

  return null;
}

// Test for a Linear UUID (user, issue, label, and other object IDs)
export function isUuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value);
}

// Resolve "me", an email, or a UUID to a user ID. Returns null if no match.
export async function resolveAssignee(assignee: string): Promise<string | null> {
  if (assignee === "me") {
    const viewer = await getViewer();
    return viewer.id as string;
  }

  // UUID - assume it's already a valid user ID
  if (isUuid(assignee)) {
    return assignee;
  }

  // Look up by email
  const userData = await graphql(`
    query { users { nodes { id email } } }
  `) as { users: { nodes: Array<{ id: string; email: string }> } };

  const user = userData.users.nodes.find((u) =>
    u.email.toLowerCase() === assignee.toLowerCase()
  );
  return user ? user.id : null;
}

// Resolve team by key or name
export async function resolveTeam(input: string): Promise<Record<string, unknown> | null> {
  const teams = await getTeams();
  const lower = input.toLowerCase();

  return teams.find((t) =>
    (t.key as string).toLowerCase() === lower ||
    (t.name as string).toLowerCase() === lower
  ) || null;
}

// Cache for workspace labels
let cachedLabels: Array<Record<string, unknown>> | null = null;

export async function getWorkspaceLabels(force = false): Promise<Array<Record<string, unknown>>> {
  if (cachedLabels && !force) return cachedLabels;

  const data = await graphql(`
    query {
      issueLabels(first: 250) { nodes { id name } }
    }
  `) as { issueLabels: { nodes: Array<Record<string, unknown>> } };

  cachedLabels = data.issueLabels.nodes;
  return cachedLabels;
}

// Resolve label names to IDs, matching names case-insensitively. Refreshes the
// cache once on a miss in case labels were created after this process started.
export async function resolveLabels(names: string[]): Promise<{ labelIds: string[]; missing: string[] }> {
  const collect = (labels: Array<Record<string, unknown>>) => {
    const labelIds: string[] = [];
    const missing: string[] = [];
    for (const name of names) {
      const label = labels.find((l) => (l.name as string).toLowerCase() === name.toLowerCase());
      if (label) labelIds.push(label.id as string);
      else missing.push(name);
    }
    return { labelIds, missing };
  };

  let result = collect(await getWorkspaceLabels());
  if (result.missing.length > 0) {
    result = collect(await getWorkspaceLabels(true));
  }
  return result;
}

async function labelError(missing: string[]): Promise<string> {
  const labels = await getWorkspaceLabels();
  const available = labels.map((l) => l.name as string).join(", ");
  return `Label "${missing.join(", ")}" not found. Available labels: ${available}`;
}

// Cache for workspace users with profile URLs (mention conversion)
let cachedUsers: Array<Record<string, unknown>> | null = null;

export async function getWorkspaceUsers(force = false): Promise<Array<Record<string, unknown>>> {
  if (cachedUsers && !force) return cachedUsers;

  const data = await graphql(`
    query { users(first: 250) { nodes { id name email url } } }
  `) as { users: { nodes: Array<Record<string, unknown>> } };

  cachedUsers = data.users.nodes;
  return cachedUsers;
}

// Convert @name mentions into Linear profile links so Linear renders them.
// A mention converts only when it maps to exactly one workspace user, by first
// name, full name with whitespace removed, or email local part
// (case-insensitive); unknown and ambiguous mentions are left untouched.
export async function convertMentions(text: string): Promise<string> {
  const users = await getWorkspaceUsers();

  const links = new Map<string, string>();
  for (const user of users) {
    const url = user.url as string | undefined;
    if (!url) continue;

    const keys = new Set<string>();
    const name = ((user.name as string) || "").toLowerCase();
    if (name) {
      keys.add(name.replace(/\s+/g, ""));
      const first = name.split(/\s+/)[0];
      if (first) keys.add(first);
    }
    const email = ((user.email as string) || "").toLowerCase();
    if (email) {
      const local = email.split("@")[0];
      if (local) keys.add(local);
    }

    for (const key of keys) {
      const existing = links.get(key);
      // An empty value marks an ambiguous key: two users, one spelling.
      if (existing !== undefined && existing !== url) {
        links.set(key, "");
      } else {
        links.set(key, url);
      }
    }
  }

  return text.replace(/(?<![\w@])@([\w][\w.-]*)/g, (match, token: string) => {
    const url = links.get(token.toLowerCase());
    return url ? `[@${token}](${url})` : match;
  });
}

// Action handlers
export async function handleSearch(query?: string | Record<string, unknown>): Promise<string> {
  const viewer = await getViewer();

  let filter = "";

  if (!query) {
    // Default: my issues, not completed, high priority
    filter = `filter: { assignee: { id: { eq: "${viewer.id}" } }, state: { type: { nin: ["completed", "canceled"] } } }`;
  } else if (typeof query === "string") {
    // Text search
    const data = await graphql(`
      query($term: String!) {
        searchIssues(term: $term, first: 20) {
          nodes {
            id identifier title state { name } priority assignee { name } dueDate
          }
        }
      }
    `, { term: query }) as { searchIssues: { nodes: Array<Record<string, unknown>> } };

    return formatIssueList(data.searchIssues.nodes);
  } else {
    // Build filter from object
    const filters: string[] = [];

    if (query.assignee === "me") {
      filters.push(`assignee: { id: { eq: "${viewer.id}" } }`);
    } else if (query.assignee) {
      // UUIDs are user IDs; anything else is treated as an email
      if (isUuid(query.assignee as string)) {
        filters.push(`assignee: { id: { eq: "${query.assignee}" } }`);
      } else {
        filters.push(`assignee: { email: { eq: "${query.assignee}" } }`);
      }
    }

    if (query.state) {
      filters.push(`state: { name: { eqIgnoreCase: "${query.state}" } }`);
    }

    if (query.priority !== undefined) {
      filters.push(`priority: { eq: ${query.priority} }`);
    }

    if (query.team) {
      const team = await resolveTeam(query.team as string);
      if (team) filters.push(`team: { id: { eq: "${team.id}" } }`);
    }

    if (filters.length > 0) {
      filter = `filter: { ${filters.join(", ")} }`;
    }
  }

  const data = await graphql(`
    query {
      issues(${filter}, first: 20, orderBy: updatedAt) {
        nodes {
          id identifier title state { name } priority assignee { name } dueDate
        }
      }
    }
  `) as { issues: { nodes: Array<Record<string, unknown>> } };

  return formatIssueList(data.issues.nodes);
}

export async function handleGet(id: string): Promise<string> {
  const resolved = resolveId(id);

  const data = await graphql(`
    query($id: String!) {
      issue(id: $id) {
        id identifier title description state { name } priority
        assignee { name email }
        labels { nodes { name } }
        dueDate estimate url
        team { id key name }
        comments(first: 5) {
          nodes { body createdAt user { name } }
        }
      }
    }
  `, { id: resolved }) as { issue: Record<string, unknown> | null };

  if (!data.issue) {
    return `Issue ${id} not found`;
  }

  const issue = data.issue;
  const labels = ((issue.labels as { nodes: Array<{ name: string }> })?.nodes || [])
    .map((l) => l.name).join(", ");

  let result = formatIssue(issue);

  if (labels) result += `\nLabels: ${labels}`;

  const comments = (issue.comments as { nodes: Array<Record<string, unknown>> })?.nodes || [];
  if (comments.length > 0) {
    result += "\n\n## Recent Comments\n";
    result += comments.map((c) =>
      `**${(c.user as Record<string, unknown>)?.name}** (${c.createdAt}):\n${c.body}`
    ).join("\n\n");
  }

  return result;
}

export async function handleUpdate(
  id: string,
  updates: { state?: string; priority?: number; assignee?: string | null; labels?: string[] }
): Promise<string> {
  const resolved = resolveId(id);

  // First get the issue to find its team
  const issueData = await graphql(`
    query($id: String!) {
      issue(id: $id) { id team { id } }
    }
  `, { id: resolved }) as { issue: { id: string; team: { id: string } } | null };

  if (!issueData.issue) {
    return `Issue ${id} not found`;
  }

  const existingIssue = issueData.issue;
  const input: Record<string, unknown> = {};

  if (updates.state) {
    const stateId = await resolveState(existingIssue.team.id, updates.state);
    if (stateId) {
      input.stateId = stateId;
    } else {
      // Get valid states for this team
      const teams = await getTeams();
      const team = teams.find((t) => t.id === existingIssue.team.id);
      const validStates = team
        ? (team.states as { nodes: Array<Record<string, unknown>> }).nodes
            .map((s) => s.name as string)
            .join(", ")
        : "unknown";
      return `State "${updates.state}" not found. Valid states: ${validStates}`;
    }
  }

  if (updates.priority !== undefined) {
    input.priority = updates.priority;
  }

  if (updates.assignee !== undefined) {
    if (updates.assignee === null) {
      input.assigneeId = null;
    } else {
      const assigneeId = await resolveAssignee(updates.assignee);
      if (assigneeId) {
        input.assigneeId = assigneeId;
      } else {
        return `Could not find user with email "${updates.assignee}"`;
      }
    }
  }

  if (updates.labels !== undefined) {
    if (updates.labels.length === 0) {
      // An empty list clears the issue's labels
      input.labelIds = [];
    } else {
      const { labelIds, missing } = await resolveLabels(updates.labels);
      if (missing.length > 0) {
        return await labelError(missing);
      }
      input.labelIds = labelIds;
    }
  }

  if (Object.keys(input).length === 0) {
    return "No updates provided";
  }

  const updateResult = await graphql(`
    mutation($id: String!, $input: IssueUpdateInput!) {
      issueUpdate(id: $id, input: $input) {
        success
        issue { identifier title state { name } priority assignee { name } labels { nodes { name } } }
      }
    }
  `, { id: existingIssue.id, input }) as { issueUpdate: { issue: Record<string, unknown> } };

  const issue = updateResult.issueUpdate.issue;
  const changes: string[] = [];
  if (updates.state) changes.push(`state → ${(issue.state as Record<string, unknown>)?.name}`);
  if (updates.priority !== undefined) changes.push(`priority → ${priorityName(issue.priority as number)}`);
  if (updates.assignee !== undefined) {
    changes.push(`assignee → ${(issue.assignee as Record<string, unknown>)?.name || "Unassigned"}`);
  }
  if (updates.labels !== undefined) {
    const labelNodes = ((issue.labels as { nodes: Array<{ name: string }> })?.nodes) || [];
    const names = labelNodes.map((l) => l.name).join(", ");
    changes.push(`labels → ${names || "none"}`);
  }

  return `Updated ${issue.identifier}: ${changes.join(", ")}`;
}

export async function handleComment(id: string, body: string): Promise<string> {
  const resolved = resolveId(id);

  // Get issue ID
  const issueData = await graphql(`
    query($id: String!) {
      issue(id: $id) { id identifier }
    }
  `, { id: resolved }) as { issue: { id: string; identifier: string } | null };

  if (!issueData.issue) {
    return `Issue ${id} not found`;
  }

  const convertedBody = await convertMentions(body);

  await graphql(`
    mutation($issueId: String!, $body: String!) {
      commentCreate(input: { issueId: $issueId, body: $body }) {
        success
      }
    }
  `, { issueId: issueData.issue.id, body: convertedBody });

  const truncated = convertedBody.length > 100 ? convertedBody.slice(0, 100) + "..." : convertedBody;
  return `Added comment to ${issueData.issue.identifier}:\n> ${truncated}`;
}

export async function handleCreate(
  title: string,
  team: string,
  options: { body?: string; priority?: number; state?: string; assignee?: string | null; labels?: string[] }
): Promise<string> {
  const teamData = await resolveTeam(team);
  if (!teamData) {
    const teams = await getTeams();
    const validTeams = teams.map((t) => `${t.key} (${t.name})`).join(", ");
    return `Team "${team}" not found. Available: ${validTeams}`;
  }

  const input: Record<string, unknown> = {
    title,
    teamId: teamData.id,
  };

  if (options.body) input.description = await convertMentions(options.body);
  if (options.priority !== undefined) input.priority = options.priority;

  if (options.state) {
    const stateId = await resolveState(teamData.id as string, options.state);
    if (stateId) {
      input.stateId = stateId;
    } else {
      const validStates = (teamData.states as { nodes: Array<Record<string, unknown>> }).nodes
        .map((s) => s.name as string)
        .join(", ");
      return `State "${options.state}" not found. Valid states: ${validStates}`;
    }
  }

  if (options.assignee) {
    const assigneeId = await resolveAssignee(options.assignee);
    if (assigneeId) {
      input.assigneeId = assigneeId;
    } else {
      return `Could not find user with email "${options.assignee}"`;
    }
  }

  if (options.labels && options.labels.length > 0) {
    const { labelIds, missing } = await resolveLabels(options.labels);
    if (missing.length > 0) {
      return await labelError(missing);
    }
    input.labelIds = labelIds;
  }

  const data = await graphql(`
    mutation($input: IssueCreateInput!) {
      issueCreate(input: $input) {
        success
        issue { identifier title url }
      }
    }
  `, { input }) as { issueCreate: { success: boolean; issue: { identifier: string; title: string; url: string } } };

  const issue = data.issueCreate.issue;
  return `Created ${issue.identifier}: ${issue.title}\n${issue.url}`;
}

export async function handleGraphql(query: string, variables?: Record<string, unknown>): Promise<string> {
  const data = await graphql(query, variables || {});
  return JSON.stringify(data, null, 2);
}

